# frozen_string_literal: true

require 'fileutils'
require 'json'
require 'open3'
require 'rbconfig'
require 'rspec'
require 'tmpdir'

# A Selenium project generated by this branch (its helper templates are byte-identical to 4.0.1's) with
# `headless: true` in config/config.yml. Its own helpers/driver_helper.rb builds the browser options, no
# browser is started. RAIDER_SHOW_BROWSER=1 drops the --headless it adds; config.yml is never written.
RSpec.describe 'Show the browser in a generated project', :slow do
  lib = File.expand_path('../../lib', __dir__)

  generate = <<~RUBY
    require 'generators/invoke_generators'
    InvokeGenerators.generate_framework(automation: 'selenium', framework: 'rspec', name: 'shown', examples: false)
  RUBY

  # Loads the project's real driver_helper and prints the args of the options it builds
  options = <<~RUBY
    require 'json'
    require './helpers/driver_helper'
    helper = Object.new.extend(DriverHelper)
    helper.instance_variable_set(:@config, YAML.load_file('config/config.yml'))
    built = helper.send(:create_webdriver_options)
    puts JSON.generate(built.as_json.fetch(built.class::KEY).fetch('args'))
  RUBY

  define_method(:ruby) do |env, dir, script|
    out, err, status = Open3.capture3(env, RbConfig.ruby, '-I', lib, '-e', script, chdir: dir)
    raise "ruby failed in #{dir}: #{err}" unless status.success?

    out
  end

  # rubocop:disable RSpec/InstanceVariable
  before(:all) do # rubocop:disable RSpec/BeforeAfterAll
    @tmp = Dir.mktmpdir('raider-show-browser')
    ruby({}, @tmp, generate)
    @project = File.join(@tmp, 'shown')
    config = File.join(@project, 'config', 'config.yml')
    File.write(config, "#{File.read(config)}headless: true\n")
    @before = File.binread(config)
    @args = { off: { 'RAIDER_SHOW_BROWSER' => nil, 'HEADLESS' => nil }, shown: { 'RAIDER_SHOW_BROWSER' => '1', 'HEADLESS' => nil },
              shown_hidden_env: { 'RAIDER_SHOW_BROWSER' => '1', 'HEADLESS' => 'true' }, other: { 'RAIDER_SHOW_BROWSER' => 'true', 'HEADLESS' => nil } }
            .transform_values { |env| JSON.parse(ruby(env, @project, options)) }
  end

  after(:all) { FileUtils.rm_rf(@tmp) } # rubocop:disable RSpec/BeforeAfterAll

  it 'requires the runtime from the generated driver_helper' do
    expect(File.read(File.join(@project, 'helpers', 'driver_helper.rb'))).to include("require 'ruby_raider/runtime'")
  end

  it 'keeps --headless without RAIDER_SHOW_BROWSER=1' do
    expect(@args.values_at(:off, :other)).to all(include('--headless'))
  end

  it 'drops --headless with RAIDER_SHOW_BROWSER=1, even with HEADLESS set, and keeps the browser arguments' do
    expected = @args[:off] - ['--headless']
    expect(@args.values_at(:shown, :shown_hidden_env)).to eq([expected, expected])
  end

  it 'never writes config.yml' do
    expect(File.binread(File.join(@project, 'config', 'config.yml'))).to eq(@before)
  end
  # rubocop:enable RSpec/InstanceVariable
end
